#include <iostream>
#include <print>
#include <string>
#include <utility>
#include <vector>

class Guard {
public:
    explicit Guard(std::string name) : name_(std::move(name)) {
        std::println("вход: {}", name_);
    }

    ~Guard() {
        std::println("выход: {}", name_);
    }

private:
    std::string name_;
};

void visit(const std::vector<std::string> &words, std::size_t i) {
    if (i == words.size()) {
        return;
    }
    Guard guard(words[i]);
    visit(words, i + 1);
}

int main() {
    std::vector<std::string> words;
    std::string word;
    while (std::cin >> word) {
        words.push_back(word);
    }
    visit(words, 0);
    return 0;
}

