#include <iostream>
#include <print>
#include <string>

class IntBuffer {
public:
    explicit IntBuffer(int size) : data_(new int[size]{}), size_(size) {}

    ~IntBuffer() {
        delete[] data_;
    }

    IntBuffer(const IntBuffer &) = delete;
    IntBuffer &operator=(const IntBuffer &) = delete;

    bool set(int i, int value) {
        if (!valid(i)) {
            return false;
        }
        data_[i] = value;
        return true;
    }

    bool get(int i, int &out) const {
        if (!valid(i)) {
            return false;
        }
        out = data_[i];
        return true;
    }

    long long sum() const {
        long long s = 0;
        for (int i = 0; i < size_; i++) {
            s += data_[i];
        }
        return s;
    }

private:
    bool valid(int i) const {
        return i >= 0 && i < size_;
    }

    int *data_;
    int size_;
};

int main() {
    int n;
    std::cin >> n;
    IntBuffer buffer(n);
    std::string command;
    while (std::cin >> command) {
        if (command == "sum") {
            std::println("{}", buffer.sum());
            continue;
        }
        int i;
        std::cin >> i;
        if (command == "set") {
            int value;
            std::cin >> value;
            if (!buffer.set(i, value)) {
                std::println("нет индекса {}", i);
            }
        } else {
            int value;
            if (buffer.get(i, value)) {
                std::println("{}", value);
            } else {
                std::println("нет индекса {}", i);
            }
        }
    }
    return 0;
}

