class Histogram {
public:
    explicit Histogram(int size) : counts_(new int[size]{}), size_(size) {}

    Histogram(const Histogram &) = delete;
    Histogram &operator=(const Histogram &) = delete;

    void add(int value) {
        if (value >= 0 && value < size_) {
            counts_[value]++;
        }
    }

    void print() const {
        for (int i = 0; i < size_; i++) {
            if (counts_[i] > 0) {
                std::println("{}: {}", i, counts_[i]);
            }
        }
    }

private:
    int *counts_;
    int size_;
};

int main() {
    Histogram h(10);
    int x;
    while (std::cin >> x) {
        h.add(x);
    }
    h.print();
    return 0;
}

