#include <cstdio>
#include <iostream>
#include <print>
#include <stdexcept>
#include <string>

class TempFile {
public:
    TempFile() : file_(std::tmpfile()) {
        if (file_ == nullptr) {
            throw std::runtime_error("не удалось создать временный файл");
        }
    }

    ~TempFile() {
        std::fclose(file_);
    }

    TempFile(const TempFile &) = delete;
    TempFile &operator=(const TempFile &) = delete;

    void write_line(const std::string &text) {
        std::fputs(text.c_str(), file_);
        std::fputc('\n', file_);
    }

    void rewind() {
        std::rewind(file_);
    }

    bool read_line(std::string &out) {
        char buffer[256];
        if (std::fgets(buffer, sizeof buffer, file_) == nullptr) {
            return false;
        }
        out = buffer;
        if (!out.empty() && out.back() == '\n') {
            out.pop_back();
        }
        return true;
    }

private:
    std::FILE *file_;
};

int main() {
    TempFile file;
    std::string line;
    while (std::getline(std::cin, line)) {
        file.write_line(line);
    }
    file.rewind();
    int count = 0;
    std::string longest;
    bool any = false;
    while (file.read_line(line)) {
        count++;
        if (!any || line.size() > longest.size()) {
            longest = line;
            any = true;
        }
    }
    std::println("строк {}", count);
    if (any) {
        std::println("самая длинная: {}", longest);
    }
    return 0;
}

